    86	/**
    87	 * Validate entity metadata against the entity type's JSON schema.
    88	 *
    89	 * Returns { valid: true } if:
    90	 * - Metadata passes schema validation
    91	 * - No schema is defined for the entity type (allows any metadata)
    92	 * - Metadata is undefined/null
    93	 *
    94	 * Returns { valid: false, errors: [...] } if validation fails.
    95	 */
    96	export async function validateEntityMetadata(
    97	  entityType: string,
    98	  metadata: Record<string, unknown> | undefined | null,
    99	  ctx: ToolContext
   100	): Promise<ValidationResult> {
   101	  // No metadata provided - valid (defaults to empty object). An explicit empty
   102	  // object still needs schema validation because the schema may require fields.
   103	  if (!metadata) {
   104	    return { valid: true };
   105	  }
   106	
   107	  // Bound untrusted input before ANY expensive work. The guard is cheap and
   108	  // short-circuits, so rejecting an oversized/deeply-nested payload here also
   109	  // saves the schema-fetch DB round-trip below — and avoids handing a DoS
   110	  // payload to AJV. Pathologically large metadata is a vector regardless of
   111	  // AJV config, so reject it as a normal validation failure.
   112	  if (exceedsValidationLimits(metadata)) {
   113	    return {
   114	      valid: false,
   115	      errors: [{ path: '/', message: 'metadata exceeds size/nesting limits' }],
   116	    };
   117	  }
   118	
   119	  // Fetch schema for this entity type
   120	  const schema = await getEntityTypeSchema(entityType, ctx);
   121	
   122	  // No schema defined - allow any metadata
   123	  if (!schema || Object.keys(schema).length === 0) {
   124	    return { valid: true };
   125	  }
   126	
   127	  // Validate metadata against schema, ignoring platform provenance keys —
   128	  // they are stamped by watcher promotion outside this validator and would
   129	  // otherwise fail every round-trip under additionalProperties: false.
   130	  const ajv = getAjv();
   131	  const validate = ajv.compile(schema);
   132	  const candidate = withoutWatcherProvenanceKeys(metadata);
   133	  const isValid = validate(candidate);
   134	  if (candidate !== metadata) {
   135	    // The AJV singleton runs with coerceTypes, mutating the validated object
   136	    // in place — callers persist those coercions. When we validated a stripped
   137	    // copy, propagate its top-level coercions back (nested objects are shared
   138	    // by reference, so deeper coercions already landed).
   139	    for (const [key, value] of Object.entries(candidate)) {
   140	      metadata[key] = value;
   141	    }
   142	  }
