 35	interface MetadataTableProperty {
 36		description?: string;
 37		enum?: string[];
 38		format?: string;
 39		"x-table-column"?: boolean;
 40		"x-table-label"?: string;
 41		"x-image"?: boolean;
 42		"x-link-entity-type"?: string;
 43		"x-link-lookup-field"?: string;
 44		// Explicit currency annotation. Preferred over the legacy name-based guess so
 45		// authored templates and columns agree on which fields are money.
 46		"x-currency"?: boolean;
 47	}
