 62	function entityPathSegments(entity: Entity): EntityPathSegment[] {
 63		if (entity.parent_id && entity.parent_slug && entity.parent_entity_type) {
 64			return [
 65				{ entity_type: entity.parent_entity_type, slug: entity.parent_slug },
 66				{ entity_type: entity.entity_type, slug: entity.slug },
 67			];
 68		}
 69		return [{ entity_type: entity.entity_type, slug: entity.slug }];
 70	}
 71	
 72	function buildEntityBrowseLink(owner: string, entity: Entity) {
 73		return memoryBrowseEntitySearch(owner, entityPathSegments(entity));
 74	}
