 76	function parseEntityMetadata(
 77		metadata: Entity["metadata"],
 78	): Record<string, unknown> {
 79		if (typeof metadata === "string") {
 80			return JSON.parse(metadata) as Record<string, unknown>;
 81		}
 82		return (metadata as Record<string, unknown> | null | undefined) ?? {};
 83	}
