 96	// Legacy name/description-based currency guess, kept as a FALLBACK for data that
 97	// predates the explicit `x-currency` annotation. New schemas should set
 98	// `x-currency: true` (or `format: "currency"`); prefer that everywhere.
 99	function looksLikeCurrencyField(
100		key: string,
101		prop: MetadataTableProperty,
102	): boolean {
103		const normalizedKey = key.toLowerCase();
104		return (
105			normalizedKey === "mrr" ||
106			normalizedKey === "arr" ||
107			normalizedKey === "revenue" ||
108			normalizedKey === "valuation" ||
109			normalizedKey === "funding_raised" ||
110			normalizedKey === "fund_size" ||
111			normalizedKey.endsWith("_usd") ||
112			prop.description?.toLowerCase().includes("usd") === true
113		);
