116	/**
117	 * Resolve a JSON-Schema property annotation to a renderer ValueFormat — the
118	 * label-driven mapping that lets both this table column AND an authored
119	 * `data`-node template format a field identically. Display itself is delegated
120	 * to the shared `formatValue`; only the currency/enum *decision* lives here
121	 * because it depends on the field name + schema annotations, not the value.
122	 */
123	function resolveColumnFormat(
124		key: string,
125		prop: MetadataTableProperty,
126	): ValueFormat {
