145	export interface EntityTableViewProps {
146		entities: Entity[];
147		owner: string;
148		schema?: EntityTableSchema;
149		entityTypeIcon?: string;
150		isDerived: boolean;
151		measureColumns: string[];
152		linkedEntityLookups: LinkedEntitiesMap;
153		hasAnyParents: boolean;
154		sorting: SortingState;
155		onSortingChange: OnChangeFn<SortingState>;
