169	 * currency formatting, relationship + derived-measure + parent + stat columns,
170	 * and a pagination footer. Registered as the `entity-table` renderer node so the
171	 * built-in table view is a one-node template while keeping all prior behavior.
172	 */
173	export function EntityTableView({
174		entities,
175		owner,
176		schema,
177		entityTypeIcon,
178		isDerived,
179		measureColumns,
180		linkedEntityLookups,
181		hasAnyParents,
182		sorting,
183		onSortingChange,
184		page,
185		pageSize,
186		totalCount,
187		hasMore,
188		pageTitle,
189		onPrevPage,
190		onNextPage,
191	}: EntityTableViewProps) {
192		const schemaProperties = schema?.properties;
193	
194		const linkedColumnSpecs = useMemo<
195			Record<string, LinkedEntityColumnSpec>
196		>(() => {
197			if (!schemaProperties) return {};
198	
199			return Object.fromEntries(
200				Object.entries(schemaProperties).flatMap(([key, prop]) => {
201					if (!prop["x-link-entity-type"]) return [];
202					return [
203						[
204							key,
205							{
206								entityType: prop["x-link-entity-type"],
207								lookupField: prop["x-link-lookup-field"] || "slug",
208							},
209						],
210					];
210					];
211				}),
212			);
213		}, [schemaProperties]);
214	
215		const schemaColumns = useMemo<ColumnDef<Entity>[]>(() => {
216			if (!schemaProperties) return [];
217	
218			const entries = Object.entries(schemaProperties).filter(
219				([, p]) => !p["x-image"] && p["x-table-column"] === true,
220			);
221	
222			return entries.map(([key, prop]) => {
223				const linkSpec = linkedColumnSpecs[key];
224				const linkedLookup = linkSpec
225					? linkedEntityLookups[getLinkedEntityLookupKey(linkSpec)]
226					: undefined;
227	
228				return {
229					id: `meta_${key}`,
230					accessorFn: (row: Entity) => {
231						const meta = parseEntityMetadata(row.metadata);
232						return normalizeEnumValue(meta[key], prop.enum);
233					},
234					header:
235						prop["x-table-label"] ||
236						prop.description ||
237						titleCaseWords(key.replace(/_/g, " ")),
238					cell: ({ getValue }: { getValue: () => unknown }) => {
239						const val = getValue();
240						const values = (Array.isArray(val) ? val : [val]).filter(
241							(item) => item != null && String(item).trim() !== "",
242						);
243	
244						if (values.length === 0) {
245							return <span className="text-muted-foreground">-</span>;
246						}
247	
248						return (
249							<div className="flex flex-wrap gap-1">
250								{values.map((item, index) => {
251									const rawValue = String(item);
252									const formattedValue = formatMetadataDisplayValue(
253										key,
254										item,
255										prop,
256									);
257									const target = linkedLookup?.[rawValue];
258									const isExternalLink =
259										prop.format === "uri" || isHttpUrl(rawValue);
260									const itemKey = target
261										? `${target.entity_type}:${target.slug}`
262										: rawValue;
263									return (
264										<span key={itemKey}>
265											{target ? (
266												(() => {
267													const link = memoryBrowseEntitySearch(owner, [
268														{
269															entity_type: target.entity_type,
270															slug: target.slug,
271														},
272													]);
273													return (
274														<Link
275															to={link.to}
276															params={link.params}
277															search={link.search}
278															className="text-primary hover:underline"
279															onClick={(e) => e.stopPropagation()}
280														>
281															{target.name}
282														</Link>
283													);
284												})()
285											) : isExternalLink ? (
286												<a
287													href={rawValue}
288													target="_blank"
289													rel="noreferrer"
290													className="text-primary hover:underline"
291													onClick={(e) => e.stopPropagation()}
292												>
293													{formattedValue}
294												</a>
295											) : (
296												<span className="text-muted-foreground">
297													{formattedValue}
298												</span>
299											)}
300											{index < values.length - 1 && ","}
301										</span>
302									);
303								})}
304							</div>
305						);
306					},
307				} satisfies ColumnDef<Entity>;
308			});
309		}, [linkedColumnSpecs, linkedEntityLookups, owner, schemaProperties]);
310	
311		// Derived ("view") rows carry arbitrary backing_sql columns in `metadata`
