   332					accessorFn: (row: Entity) => parseEntityMetadata(row.metadata)[key],
   333					header: () => (
   334						<span className="flex items-center gap-1.5">
   335							{isMeasure ? key : titleCaseWords(key.replace(/_/g, " "))}
   336							{isMeasure && (
   337								<Badge variant="secondary" className="font-normal lowercase">
   338									measure
   339								</Badge>
   340							)}
   341						</span>
   342					),
   343					cell: ({ getValue }: { getValue: () => unknown }) => (
   344						<span
   345							className={isMeasure ? "tabular-nums" : "text-muted-foreground"}
   346						>
   347							{formatDerivedValue(getValue())}
   348						</span>
   349					),
   350					meta: isMeasure ? { align: "right" } : undefined,
   351				} satisfies ColumnDef<Entity>;
   352			});
   353		}, [isDerived, schemaColumns, entities, measureColumnSet]);
   354	
   355		const relationshipColumns = useMemo<ColumnDef<Entity>[]>(() => {
   356			const specs = schema?.["x-table-relationships"];
   357			if (!specs || specs.length === 0) return [];
   358	
   359			return specs.map((spec) => ({
   360				id: `rel_${spec.relationship_type}`,
   361				accessorFn: (row: Entity) =>
   362					row.relationships?.[spec.relationship_type] ?? [],
   363				header: spec.label,
   364				cell: ({ getValue }: { getValue: () => unknown }) => {
   365					const related = getValue() as
   366						| Array<{
   367								id: number;
   368								name: string;
   369								slug: string;
   370								entity_type: string;
   371						  }>
   372						| undefined;
   373					if (!related || related.length === 0) {
   374						return <span className="text-muted-foreground">-</span>;
   375					}
   376					return (
   377						<div className="flex flex-wrap gap-1">
   378							{related.map((r, i) => {
   379								const link = memoryBrowseEntitySearch(owner, [
   380									{ entity_type: r.entity_type, slug: r.slug },
   381								]);
   382								return (
   383									<span key={r.id}>
   384										<Link
   385											to={link.to}
   386											params={link.params}
   387											search={link.search}
   388											className="text-primary hover:underline"
   389											onClick={(e) => e.stopPropagation()}
   390										>
   391											{r.name}
   392										</Link>
   393										{i < related.length - 1 && ","}
   394									</span>
   395								);
   396							})}
   397						</div>
   398					);
   399				},
   400			}));
   401		}, [owner, schema]);
   402	
   403		const parentColumn = useMemo<ColumnDef<Entity>[]>(() => {
   404			const hasParents =
   405				hasAnyParents ||
   406				entities.some(
   407					(entity) =>
   408						entity.parent_name && entity.parent_slug && entity.parent_entity_type,
   409				);
   410			if (!hasParents) return [];
   411	
   412			return [
   413				{
   414					id: "parent",
   415					accessorFn: (row: Entity) => row.parent_name,
   416					header: "Parent",
   417					cell: ({ row }) => {
   418						if (
   419							!row.original.parent_name ||
   420							!row.original.parent_slug ||
   421							!row.original.parent_entity_type
   422						) {
   423							return <span className="text-muted-foreground">-</span>;
   424						}
   425	
   426						const link = memoryBrowseEntitySearch(owner, [
   427							{
   428								entity_type: row.original.parent_entity_type,
   429								slug: row.original.parent_slug,
   430							},
"}

