     1	/**
     2	 * Entity mutation policy — the single decision layer for whether an agent or
     3	 * watcher write to an entity applies immediately or queues a durable approval.
     4	 *
     5	 * Two inputs, one decision:
     6	 *  - Built-in invariants that no org policy can disable: writes never cross
     7	 *    organizations, and a non-human write to a human-owned field always needs
     8	 *    approval (field ownership is how a user pins a value).
     9	 *  - The org's persisted `write_approval_policies` rows: per-action
    10	 *    auto/approval modes, scoped global → entity type → field → single entity
    11	 *    (entity_id), most specific row wins. Rows also carry the Slack delivery
    12	 *    target for approval notifications.
    13	 *
    14	 * Human edits are never gated here — role restrictions for humans live in the
    15	 * tool-access tier (e.g. manage_entity delete is owner/admin).
    16	 *
    17	 * Gated paths: manage_entity create/update/delete and watcher window promotion
    18	 * (promote-keyed-entities). Ingestion-infrastructure writes (entity-link-upsert
    19	 * identity stubs, classifier extraction) are exempt BY DESIGN — they are
    20	 * high-volume provenance plumbing, not collaboration edits; gating them would
    21	 * flood approvals. Any new user-facing entity write path MUST call this module.
    22	 */
    23	import { type DbClient, getDb, pgBigintArray, pgTextArray } from "../db/client";
    24	import {
    25		WRITE_ACTION_MANIFEST,
    26		type WriteAction,
    27		defaultEffectFor,
    28		isLegalActionEffect,
    29	} from "./write-action-manifest";
    30	
    31	export type EntityPolicyDecision = "allow" | "deny" | "require_approval";
    32	export type EntityPolicyPrincipalKind = "user" | "agent" | "watcher";
    33	export type EntityMutationAction = "read" | "create" | "update" | "delete";
    34	/**
    35	 * A stored per-action mode. `auto`/`approval` are the two entity modes; `deny`
    36	 * (a hard floor — the write never applies and no approval is queued) and
    37	 * `disabled` (the action is turned off entirely, used by the connector-action
    38	 * class) are admitted by the widened DB CHECK. The resolver maps each to an
    39	 * {@link EntityPolicyDecision}; unknown values coerce to the caller's fallback
    40	 * so a mode this build predates can never silently read as `allow`.
   770	export async function evaluateEntityMutation(args: {
   771		organizationId: string;
   772		principalKind: EntityPolicyPrincipalKind;
   773		/** Stable acting-principal id for per-principal matching; null = any of its kind. */
   774		principalId?: string | null;
   775		/**
   776		 * The owning agent of a watcher — folds the agent's rows in alongside the
   777		 * watcher's, max-restrictive. See {@link loadCandidatePolicies}.
   778		 */
   779		ownerAgentId?: string | null;
   780		action: EntityMutationAction;
   781		entityTypeSlug?: string | null;
   782		entityId?: number | null;
   783		entityOrgId?: string | null;
   784		/**
   785		 * False iff the acting principal is a watcher whose owning agent could not be
   786		 * resolved (its row is gone). Fail CLOSED — the agent envelope can't be folded,
   787		 * so we deny rather than run the write against the looser org default. Defaults
   788		 * true (agent/user turns, and watchers whose owner resolved).
   789		 */
   790		ownerResolved?: boolean;
   791		sql?: DbClient;
   792	}): Promise<EntityPolicyDecision> {
   793		if (args.entityOrgId && args.entityOrgId !== args.organizationId) {
   794			return "deny";
   795		}
   796		if (args.principalKind === "user") return "allow";
   797		if (args.ownerResolved === false) return "deny";
   798		const candidates = await loadCandidatePolicies({
   799			...args,
   800			principalKind: args.principalKind,
   801			principalId: args.principalId ?? null,
   802			ownerAgentId: args.ownerAgentId ?? null,
   803		});
   804		// create/delete/read act on the WHOLE entity, not any one field — a field-scoped
   805		// row (e.g. person.ssn=deny) governs only its field's UPDATES and must not
   806		// bleed into the entity's create/delete/read decision. Drop field-scoped rows here
   807		// (the update path keeps them, matched per-field). What remains — the org
   808		// floor, blanket, and type-scoped rows — folds max-restrictive.
   809		const forEntity = candidates.filter((row) => row.field_path === null);
   810		const decision = modeToDecision(
   811			foldEffectForDecision(forEntity, "entity", args.action),
   812		);
   813		// Reads never queue: approval is treated as deny (stricter than auto, no inbox).
   814		if (args.action === "read" && decision === "require_approval") return "deny";
   815		return decision;
   816	}
